css:
.loader { position: relative; overflow: hidden; width: var(--loader-size); height: calc(var(--loader-size) * .4); }
.loader .toast { position: absolute; top: 0; bottom: 0; right: 0; display: flex; flex-direction: column; justify-content: center; gap: calc(var(--loader-size) * .05); width: 82%; padding: 0 calc(var(--loader-size) * .07); border-radius: calc(var(--loader-size) * .06); background: color-mix(in srgb, var(--loader-color) 16%, transparent); border-left: calc(var(--loader-size) * .04) solid var(--loader-color); box-sizing: border-box; animation: twToast calc(var(--loader-speed) * 2.4) cubic-bezier(.4, 0, .2, 1) infinite; }
.loader .toast i { height: calc(var(--loader-size) * .05); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 45%, transparent); }
.loader .toast i:last-child { width: 60%; }
@keyframes twToast { 0% { transform: translateX(110%); opacity: 0; } 15%, 70% { transform: translateX(0); opacity: 1; } 90%, 100% { transform: translateX(110%); opacity: 0; } }
